import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container – could be a Group if we need future children
  const container = new Group();

  // Geometry for the card plane (aspect ratio guessed)
  const geometry = new PlaneGeometry(2, 1.2);

  // Basic node material that will receive the texture
  const material = new MeshBasicNodeMaterial({ transparent: true });
  let loadedTexture = null;

  // Load the texture asynchronously; will be applied when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  const mesh = new Mesh(geometry, material);
  container.add(mesh);

  // No interactive handlers for this node
  container.userData.handlers = {};

  // Cleanup resources and any GSAP timelines (none here but kept for pattern)
  container.userData.cleanup = () => {
    // Dispose GSAP timelines if any were created in the future
    gsap.globalTimeline.clear();

    if (loadedTexture) {
      loadedTexture.dispose();
      loadedTexture = null;
    }
    material.dispose();
    geometry.dispose();
    // Remove from parent if still attached
    if (container.parent) {
      container.parent.remove(container);
    }
  };

  return container;
}
